import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Handl SDK Generator — JVM Backend","description":"","frontmatter":{"title":"Handl SDK Generator — JVM Backend","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"proposed","status_note":"Proposed."},"headers":[],"relativePath":"c/project/adrs/0111-handl-sdkgen-jvm.md","filePath":"vendored/c/project/adrs/0111-handl-sdkgen-jvm.md"}`),a={name:`c/project/adrs/0111-handl-sdkgen-jvm.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0111-handl-sdk-generator-—-jvm-backend" tabindex="-1">ADR-0111: Handl SDK Generator — JVM Backend <a class="header-anchor" href="#adr-0111-handl-sdk-generator-—-jvm-backend" aria-label="Permalink to “ADR-0111: Handl SDK Generator — JVM Backend”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Add a <code>plugin-sdkgen-backend-jvm</code> crate that parses Java class / method signatures (directly or from <code>.class</code> / <code>.jar</code> metadata) and produces <code>SdkgenModule</code> records.</p><ul><li>The backend may start by consuming a list of Java method signatures or a reflection dump; later it can read <code>.class</code> files or use a lightweight parser.</li><li>The <code>client_package</code> for the generated adapter is <code>jvm</code>.</li><li>The adapter uses <code>jvm.call</code> / <code>jvm.exception</code> primitives (a new <code>jvm</code> client package similar to <code>ffi</code>) to invoke methods and translate exceptions into <code>Result&lt;_, JvmException&gt;</code>.</li><li>Map common Java types to Handl types: <ul><li><code>int</code> / <code>Integer</code> → <code>Int</code> (<code>i32</code>)</li><li><code>long</code> / <code>Long</code> → <code>Int</code> (<code>i64</code>)</li><li><code>double</code> / <code>Double</code> → <code>Float</code> (<code>f64</code>)</li><li><code>String</code> → <code>String</code> (<code>jstring</code>)</li><li><code>byte[]</code> / <code>ByteBuffer</code> → <code>Bytes</code> (<code>jbyte_array</code>)</li><li>Object references → <code>Handle</code> (<code>jobject</code>)</li><li><code>void</code> → <code>()</code></li></ul></li><li>Support class-name to package mapping, method overloads via name mangling, and static vs instance method dispatch.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><a href="./0107-handl-sdk-generator.html">ADR-0107 — Handl SDK Generator</a> established a backend-agnostic IR (<code>SdkgenModule</code>) and a port-adapter emitter architecture. The first concrete backend is C / libclang. The next high-priority backend is the JVM, which lets Handl call Java libraries and native Java classes through JNI.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li>none recorded — legacy record; the design doc lists what was deferred.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Handl can consume the huge ecosystem of JVM libraries.</li><li>A <code>jvm</code> client package must be designed and implemented, paralleling <code>ffi</code>.</li><li>Overloaded Java methods require a name-mangling scheme in the port.</li><li>This backend is higher priority than Bukkit / Spigot / Paper (ADR-0112) and</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li>Code and tests are named in the design doc.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>The full record (context, tables, phases, trade-offs): <a href="./../design/0111-handl-sdkgen-jvm.html"><code>design/0111-handl-sdkgen-jvm.md</code></a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};